-- ts-design-studio 0.2.0 – konverzace s AI a spotřeba modelu (SQLite)
CREATE TABLE IF NOT EXISTS studio_messages (id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER NOT NULL, num INTEGER NOT NULL DEFAULT 0, uid INTEGER NOT NULL DEFAULT 0, role VARCHAR(10) NOT NULL, text TEXT NOT NULL, created_at VARCHAR(19) NOT NULL);
CREATE INDEX IF NOT EXISTS studio_messages_project ON studio_messages (project_id, id);
CREATE TABLE IF NOT EXISTS studio_usage (id INTEGER PRIMARY KEY AUTOINCREMENT, day VARCHAR(10) NOT NULL, project_id INTEGER NOT NULL DEFAULT 0, uid INTEGER NOT NULL DEFAULT 0, kind VARCHAR(10) NOT NULL, model VARCHAR(80) NOT NULL, tokens_in INTEGER NOT NULL DEFAULT 0, tokens_out INTEGER NOT NULL DEFAULT 0, neurons INTEGER NOT NULL DEFAULT 0, ok INTEGER NOT NULL DEFAULT 1, created_at VARCHAR(19) NOT NULL);
CREATE INDEX IF NOT EXISTS studio_usage_day ON studio_usage (day);
